package com.clinicqueue.web;
import com.clinicqueue.model.*; import com.clinicqueue.repo.*; import com.clinicqueue.security.JwtService; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.security.Principal; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api") public class ApiController {
 private final UserRepository users; private final AppointmentRepository appointments; private final PasswordEncoder encoder; private final JwtService jwt;
 public ApiController(UserRepository u,AppointmentRepository a,PasswordEncoder e,JwtService j){users=u;appointments=a;encoder=e;jwt=j;}
 record Register(String name,String email,String password,Role role){} record Login(String email,String password){} record Booking(Long doctorId,LocalDate date,LocalTime time){} record StatusUpdate(String status){}
 @PostMapping("/auth/register") public Map<String,Object> register(@RequestBody Register r){if(users.findByEmail(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");var u=users.save(new AppUser(r.name(),r.email(),encoder.encode(r.password()),Role.PATIENT));return token(u);}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Login r){var u=users.findByEmail(r.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!encoder.matches(r.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return token(u);}
 private Map<String,Object> token(AppUser u){return Map.of("token",jwt.generate(u.getEmail(),u.getRole().name()),"name",u.getName(),"email",u.getEmail(),"role",u.getRole());}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP");}
 @GetMapping("/doctors") public List<Map<String,Object>> doctors(){return users.findByRole(Role.DOCTOR).stream().map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName())).toList();}
 @GetMapping("/doctors/{id}/slots") public List<Map<String,Object>> slots(@PathVariable Long id,@RequestParam LocalDate date){if(users.findById(id).filter(u->u.getRole()==Role.DOCTOR).isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Doctor not found");Set<LocalTime> booked=new HashSet<>();appointments.findSlots(id,date).forEach(a->booked.add(a.getTime()));return java.util.stream.IntStream.range(0,16).mapToObj(i->LocalTime.of(9,0).plusMinutes(i*30)).filter(t->!booked.contains(t)).map(t->Map.<String,Object>of("time",t.toString())).toList();}
 @PostMapping("/appointments") @PreAuthorize("hasRole('PATIENT')") public Map<String,Object> book(@RequestBody Booking b,Principal principal){var patient=users.findByEmail(principal.getName()).orElseThrow();var doctor=users.findById(b.doctorId()).filter(u->u.getRole()==Role.DOCTOR).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Doctor not found"));if(b.date().isBefore(LocalDate.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Date must be today or later");if(appointments.existsByDoctorIdAndDateAndTimeAndStatusNot(doctor.getId(),b.date(),b.time(),"CANCELLED"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Slot already booked");var a=appointments.save(new Appointment(patient,doctor,b.date(),b.time()));return Map.of("id",a.getId(),"doctor",doctor.getName(),"date",a.getDate(),"time",a.getTime(),"status",a.getStatus());}
 @GetMapping("/appointments/my") @PreAuthorize("hasRole('PATIENT')") public List<Map<String,Object>> mine(Principal p){var u=users.findByEmail(p.getName()).orElseThrow();return appointments.findByPatientIdOrderByDateAscTimeAsc(u.getId()).stream().map(this::view).toList();}
 @GetMapping("/appointments") @PreAuthorize("hasAnyRole('ADMIN','DOCTOR')") public List<Map<String,Object>> all(){return appointments.findAllRecent().stream().map(this::view).toList();}
 @PatchMapping("/appointments/{id}/status") @PreAuthorize("hasAnyRole('ADMIN','DOCTOR')") public Map<String,Object> update(@PathVariable Long id,@RequestBody StatusUpdate s){if(!Set.of("CONFIRMED","COMPLETED","CANCELLED").contains(s.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported status");var a=appointments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));a.setStatus(s.status());return view(appointments.save(a));}
 @GetMapping("/admin/summary") @PreAuthorize("hasRole('ADMIN')") public Map<String,Object> summary(){return Map.of("patients",users.findByRole(Role.PATIENT).size(),"doctors",users.findByRole(Role.DOCTOR).size(),"appointments",appointments.count());}
 private Map<String,Object> view(Appointment a){return Map.of("id",a.getId(),"patient",a.getPatient().getName(),"doctor",a.getDoctor().getName(),"date",a.getDate(),"time",a.getTime(),"status",a.getStatus());}
}
